"use client";

import { useEffect, useId, useRef, useState } from "react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { cn } from "@/lib/utils";

import { measureClinics, rankRegions, REGION_METRICS, type RegionMetricId, SERVICE_REGIONS } from "../lib/choropleth-regions";
import { formatOnePlace, formatWhole } from "../lib/format";
import { ROLL_ONE_PLACE, ROLL_WHOLE } from "../lib/roll-formats";
import { BlockFrame } from "../parts/block-frame";
import { RankedList } from "./choropleth-explorer/ranked-list";
import { RegionDetail } from "./choropleth-explorer/region-detail";
import { ScaleLegend } from "./choropleth-explorer/scale-legend";
import { TileMap } from "./choropleth-explorer/tile-map";

const ALL_CLINICS = SERVICE_REGIONS.flatMap((region) => region.clinics);

// How the rolling headline figure is written for each figure, and the few words after it.
const HEADLINE_ROLL = {
  bookings: { format: ROLL_WHOLE, whole: true, suffix: "", words: "bookings, last 30 days" },
  noShowRate: { format: ROLL_ONE_PLACE, whole: false, suffix: "%", words: "of bookings were no-shows" },
  wait: { format: ROLL_ONE_PLACE, whole: false, suffix: " days", words: "average wait" },
} satisfies Record<RegionMetricId, { format: Intl.NumberFormatOptions; whole: boolean; suffix: string; words: string }>;

// A bare number for a legend label: the figure's unit is already in the header line.
const LEGEND_NUMBER = {
  bookings: formatWhole,
  noShowRate: formatOnePlace,
  wait: formatOnePlace,
} satisfies Record<RegionMetricId, (value: number) => string>;

/**
 * A map of Fernhill's service regions, shaded on a five-step scale by one of
 * three figures. The ranked list beside it shares its cursor with the map,
 * and opening a region zooms the map in and lists that region's clinics.
 */
export function ChoroplethExplorer({ className }: { className?: string }) {
  const [metricId, setMetricId] = useState<RegionMetricId>("bookings");
  const [sweep, setSweep] = useState(false);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [pickedStep, setPickedStep] = useState<number | null>(null);
  const titleId = useId();
  const listRef = useRef<HTMLDivElement>(null);
  const backRef = useRef<HTMLButtonElement>(null);
  const wasOpen = useRef(false);

  // Opening a region moves focus to the way back, and closing it returns focus to the list.
  useEffect(() => {
    if (selectedId) backRef.current?.focus();
    else if (wasOpen.current) listRef.current?.focus();
    wasOpen.current = selectedId !== null;
  }, [selectedId]);

  const metric = REGION_METRICS.find((item) => item.id === metricId) ?? REGION_METRICS[0]!;
  const { ranked, steps } = rankRegions(metricId);
  const selected = ranked.find((item) => item.region.id === selectedId) ?? null;
  const inspected = ranked.find((item) => item.region.id === activeId) ?? selected;
  const top = ranked[0];
  const bottom = ranked[ranked.length - 1];
  const picked = pickedStep === null ? null : steps[pickedStep];
  const headline = measureClinics(ALL_CLINICS, metricId);
  const headlineRoll = HEADLINE_ROLL[metricId];
  const rankOf = (rank: number) => `${rank} of ${ranked.length} for ${metric.label.toLowerCase()}`;

  // The visible sentence never changes on hover: the map labels the region under the pointer.
  const summary = top && bottom ? `${top.region.name} is highest, ${bottom.region.name} lowest.` : "";
  let readout = "";
  if (inspected) readout = `${inspected.region.name}: ${metric.format(inspected.value)}, ranked ${rankOf(inspected.rank)}.`;
  else if (picked) readout = `${picked.count} ${picked.count === 1 ? "region" : "regions"} from ${metric.format(picked.from)} to ${metric.format(picked.to)}.`;

  const changeMetric = (next: RegionMetricId) => {
    setSweep(true);
    setPickedStep(null);
    setMetricId(next);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Service regions
          </h2>
          <p className="truncate text-sm text-muted-foreground">
            <span className="tabular-nums">
              <NumberTicker value={headlineRoll.whole ? Math.round(headline) : headline} format={headlineRoll.format} />
              {headlineRoll.suffix}
            </span>{" "}
            {headlineRoll.words}
          </p>
        </div>
        <SegmentedControl aria-label="Figure on the map" options={REGION_METRICS.map(({ id, label }) => ({ value: id, label }))} value={metricId} onValueChange={changeMetric} />
      </header>

      <div className="grid @3xl:grid-cols-[1fr_21rem]">
        <div className="flex min-w-0 flex-col gap-3 p-5">
          <p className="h-5 truncate text-sm text-muted-foreground">{summary}</p>
          <p aria-live="polite" className="sr-only">
            {readout}
          </p>
          <TileMap
            regions={ranked}
            figureKey={metricId}
            sweep={sweep}
            activeId={activeId}
            selectedId={selectedId}
            pickedStep={pickedStep}
            formatValue={metric.format}
            onHover={setActiveId}
            onSelect={setSelectedId}
          />
          <ScaleLegend steps={steps} formatValue={metric.format} formatNumber={LEGEND_NUMBER[metricId]} pickedStep={pickedStep} onPickedStepChange={setPickedStep} />
        </div>
        {/* The list and the detail share one grid cell, so opening a region never changes the block's height. */}
        <div className="grid min-w-0 border-t border-border p-5 @3xl:border-t-0 @3xl:border-l">
          {selected ? (
            <div className="col-start-1 row-start-1 min-w-0">
              <RegionDetail region={selected.region} rankText={rankOf(selected.rank)} onBack={() => setSelectedId(null)} backRef={backRef} />
            </div>
          ) : null}
          {/* Hidden and inert while a region is open. It stays in the layout to hold the height. */}
          <div inert={selected !== null} aria-hidden={selected !== null} className={cn("col-start-1 row-start-1 flex min-w-0 flex-col gap-2", selected ? "invisible" : undefined)}>
              <h3 className="truncate text-sm font-medium">{metric.label} by region</h3>
              <RankedList
                label={`Regions by ${metric.label.toLowerCase()}, highest first`}
                regions={ranked}
                formatValue={metric.format}
                activeId={activeId}
                onActiveChange={setActiveId}
                onSelect={setSelectedId}
                pickedStep={pickedStep}
                listRef={listRef}
              />
          </div>
        </div>
      </div>
    </BlockFrame>
  );
}

/**
 * Data and tile maths for the region map block. The territory is invented: a
 * hand-laid cluster of hexagon tiles, one per Fernhill service region. No tile
 * follows a real border.
 */
import { formatOnePlace, formatWhole } from "./format";
import { seededRandom } from "./plot";

/** A figure the map can shade by. */
export type RegionMetricId = "bookings" | "noShowRate" | "wait";

/** One clinic in a region, with its last 30 days. */
export interface RegionClinic {
  name: string;
  bookings: number;
  /** Bookings where the patient did not attend. */
  noShows: number;
  /** Days until the next free slot. */
  waitDays: number;
}

/** One service region and its tile. */
export interface ServiceRegion {
  id: string;
  name: string;
  /** The tile's centre, as a percent of the map's width and height. */
  x: number;
  y: number;
  /** The tile's outline in map units, for an SVG polygon. */
  outline: string;
  clinics: RegionClinic[];
}

/** A figure with its labels and formatter. */
export interface RegionMetric {
  id: RegionMetricId;
  label: string;
  /** Completes "Fernhill had 12,345 ...". */
  headline: string;
  format: (value: number) => string;
}

/** The three figures. */
export const REGION_METRICS: RegionMetric[] = [
  { id: "bookings", label: "Bookings", headline: "bookings across every region in the last 30 days", format: formatWhole },
  { id: "noShowRate", label: "No-shows", headline: "of bookings ended in a no-show", format: (value) => `${formatOnePlace(value)}%` },
  { id: "wait", label: "Wait", headline: "is the average wait for a free slot", format: (value) => `${formatOnePlace(value)} days` },
];

// Pointy-top hexagons. A tile is 2 radii tall, and rows sit 1.5 radii apart.
const RADIUS = 10;
const TILE_WIDTH = Math.sqrt(3) * RADIUS;

/** The size of the map in its own units, for the SVG view box. */
export const MAP_WIDTH = 4.5 * TILE_WIDTH;
/** The height of the map in its own units. */
export const MAP_HEIGHT = 6.5 * RADIUS;

// Name, row, and place across the row in tile widths. Odd rows sit half a tile to the right.
const TILES: [string, number, number][] = [
  ["Aldervale", 0, 1],
  ["Brackenmoor", 0, 2],
  ["Calder Reach", 0, 3],
  ["Dunmere", 1, 0.5],
  ["Eastfold", 1, 1.5],
  ["Fenshore", 1, 2.5],
  ["Greyholm", 1, 3.5],
  ["Harrowmead", 2, 1],
  ["Kestrel Down", 2, 2],
  ["Larchfield", 2, 3],
  ["Marrow Bay", 2, 4],
  ["Nethercombe", 3, 1.5],
  ["Oakhaven", 3, 2.5],
  ["Pennant Hill", 3, 3.5],
];

const CLINIC_WORDS = ["Tanner", "Willow", "Bell", "Copper", "Heron", "Foundry", "Meadow", "Linden", "Ferry", "Abbey", "Cooper", "Lantern", "Rowan", "Sorrel"];
const CLINIC_ENDINGS = ["Row", "Court", "Yard"];

function tileOutline(centreX: number, centreY: number): string {
  // A little short of the full radius, so neighbours show a gap between them.
  const radius = RADIUS - 0.6;
  return Array.from({ length: 6 }, (_, corner) => {
    const angle = (Math.PI / 180) * (60 * corner - 90);
    return `${(centreX + radius * Math.cos(angle)).toFixed(2)},${(centreY + radius * Math.sin(angle)).toFixed(2)}`;
  }).join(" ");
}

function buildRegions(): ServiceRegion[] {
  const random = seededRandom(29);
  return TILES.map(([name, row, across], index) => {
    const centreX = across * TILE_WIDTH;
    const centreY = RADIUS + row * 1.5 * RADIUS;
    const size = 0.6 + random() * 0.9;
    const clinics = CLINIC_ENDINGS.map((ending, place): RegionClinic => {
      const bookings = Math.round((170 + random() * 380) * size);
      return {
        name: `${CLINIC_WORDS[(index * 3 + place) % CLINIC_WORDS.length]} ${ending}`,
        bookings,
        noShows: Math.round(bookings * (0.03 + random() * 0.09)),
        waitDays: Math.round((1 + random() * 8) * 10) / 10,
      };
    });
    return {
      id: name.toLowerCase().replaceAll(" ", "-"),
      name,
      x: (centreX / MAP_WIDTH) * 100,
      y: (centreY / MAP_HEIGHT) * 100,
      outline: tileOutline(centreX, centreY),
      clinics,
    };
  });
}

/** The fourteen service regions. */
export const SERVICE_REGIONS: ServiceRegion[] = buildRegions();

/**
 * One figure for a set of clinics. Bookings add up, the no-show rate divides
 * no-shows by bookings, and the wait is weighted by bookings, so a region's
 * figure always follows from its clinics.
 */
export function measureClinics(clinics: RegionClinic[], metric: RegionMetricId): number {
  const bookings = clinics.reduce((total, clinic) => total + clinic.bookings, 0);
  if (metric === "bookings") return bookings;
  if (bookings === 0) return 0;
  if (metric === "noShowRate") return (clinics.reduce((total, clinic) => total + clinic.noShows, 0) / bookings) * 100;
  return clinics.reduce((total, clinic) => total + clinic.waitDays * clinic.bookings, 0) / bookings;
}

/** How many steps the scale has. */
export const SCALE_STEPS = 5;

/** A region with its figure, its step on the scale and its rank, highest first. */
export interface RankedRegion {
  region: ServiceRegion;
  value: number;
  /** From 0, the lowest step, to 4. */
  step: number;
  /** From 1, the highest value. */
  rank: number;
}

/** One step of the scale: the values it covers and how many regions fall in it. */
export interface ScaleStep {
  from: number;
  to: number;
  count: number;
}

/** The regions ranked on one figure, and the scale they are shaded on. */
export interface RegionRanking {
  ranked: RankedRegion[];
  steps: ScaleStep[];
}

/** Every region ranked on one figure, with the five equal steps between the lowest and highest value. */
export function rankRegions(metric: RegionMetricId): RegionRanking {
  const values = SERVICE_REGIONS.map((region) => measureClinics(region.clinics, metric));
  const low = Math.min(...values);
  const span = Math.max(...values) - low || 1;
  const stepOf = (value: number) => Math.min(SCALE_STEPS - 1, Math.floor(((value - low) / span) * SCALE_STEPS));
  const ranked = SERVICE_REGIONS.map((region, index) => ({ region, value: values[index] ?? 0, step: stepOf(values[index] ?? 0), rank: 0 }))
    .sort((a, b) => b.value - a.value)
    .map((item, index) => ({ ...item, rank: index + 1 }));
  const steps = Array.from({ length: SCALE_STEPS }, (_, step) => ({
    from: low + (span * step) / SCALE_STEPS,
    to: low + (span * (step + 1)) / SCALE_STEPS,
    count: ranked.filter((item) => item.step === step).length,
  }));
  return { ranked, steps };
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

// NumberTicker memoises its formatter on the options object, so every block
// passes one of these constants and never an inline object.

/** A whole number with thousands separators, for a rolling figure. */
export const ROLL_WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

/** A number with one decimal place, for a rolling figure. */
export const ROLL_ONE_PLACE: Intl.NumberFormatOptions = { minimumFractionDigits: 1, maximumFractionDigits: 1 };

/** A dollar amount with no cents, for a rolling figure. */
export const ROLL_MONEY: Intl.NumberFormatOptions = { style: "currency", currency: "USD", maximumFractionDigits: 0 };

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { type KeyboardEvent, type Ref, useId } from "react";

import { cn } from "@/lib/utils";

import type { RankedRegion } from "../../lib/choropleth-regions";
import { STEP_SURFACE } from "./step-colours";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for the ranked list of regions. */
export interface RankedListProps {
  /** Names the list, such as "Regions by bookings, highest first". */
  label: string;
  regions: RankedRegion[];
  formatValue: (value: number) => string;
  /** The region under the cursor, shared with the map. */
  activeId: string | null;
  onActiveChange: (id: string | null) => void;
  onSelect: (id: string) => void;
  /** A step picked on the legend. Rows on other steps fade back. */
  pickedStep: number | null;
  /** The list element, so focus can return to it when a region's detail closes. */
  listRef: Ref<HTMLDivElement>;
}

/**
 * Every region, highest value first. It is one tab stop and the keyboard
 * path to the map: arrows walk the rows and outline each region on the map,
 * Home and End jump, Enter or Space opens the region, Escape clears.
 */
export function RankedList({ label, regions, formatValue, activeId, onActiveChange, onSelect, pickedStep, listRef }: RankedListProps) {
  const baseId = useId();
  const position = regions.findIndex((item) => item.region.id === activeId);
  const largest = Math.max(...regions.map((item) => item.value), 1);

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const last = regions.length - 1;
    let next = position;
    if (event.key === "ArrowDown") next = Math.min(last, position + 1);
    else if (event.key === "ArrowUp") next = Math.max(0, position - 1);
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = last;
    else if ((event.key === "Enter" || event.key === " ") && activeId) onSelect(activeId);
    else if (event.key === "Escape" && activeId) next = -1;
    else return;
    event.preventDefault();
    if (next !== position) onActiveChange(regions[next]?.region.id ?? null);
  };

  return (
    <div
      ref={listRef}
      role="listbox"
      tabIndex={0}
      aria-label={`${label}. Use the arrow keys to walk the regions and Enter to open one.`}
      aria-activedescendant={activeId ? `${baseId}-${activeId}` : undefined}
      onKeyDown={onKeyDown}
      onFocus={() => {
        if (!activeId) onActiveChange(regions[0]?.region.id ?? null);
      }}
      onBlur={() => onActiveChange(null)}
      className="group flex flex-col gap-0.5 rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      {regions.map(({ region, value, step, rank }) => {
        const active = region.id === activeId;
        return (
          <div
            key={region.id}
            id={`${baseId}-${region.id}`}
            role="option"
            aria-selected={active}
            onPointerEnter={() => onActiveChange(region.id)}
            onPointerLeave={() => onActiveChange(null)}
            onClick={() => onSelect(region.id)}
            className={cn(
              "relative isolate flex min-h-11 cursor-pointer items-center gap-3 rounded-md px-2 text-sm whitespace-nowrap sm:min-h-9",
              active ? "bg-muted/60 group-focus-visible:ring-2 group-focus-visible:ring-ring" : undefined,
              pickedStep !== null && pickedStep !== step ? "opacity-40" : undefined,
            )}
          >
            {/* The value as a soft bar behind the row. It has the row's own corners, so the hover surface and the bar read as one piece. */}
            <span
              aria-hidden="true"
              className={cn(
                "w-(--w) absolute inset-y-0 left-0 -z-10 rounded-md motion-safe:transition-colors motion-safe:duration-150",
                active ? "bg-foreground/10" : "bg-muted",
              )}
              style={
                // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                { "--w": `${(value / largest) * 100}%` } as VarStyle
              }
            />
            <span className="w-5 shrink-0 text-right text-xs tabular-nums text-muted-foreground">{rank}</span>
            <span aria-hidden="true" className={cn("size-3 shrink-0 rounded-sm border border-border", STEP_SURFACE[step])} />
            <span className="min-w-0 flex-1 truncate">{region.name}</span>
            <span className="shrink-0 tabular-nums text-muted-foreground">{formatValue(value)}</span>
          </div>
        );
      })}
    </div>
  );
}

