export const STEP_FILL = ["fill-chart-1/15", "fill-chart-1/30", "fill-chart-1/50", "fill-chart-1/70", "fill-chart-1/90"];

/** The same five steps as a background, for a legend swatch or a list marker. */
export const STEP_SURFACE = ["bg-chart-1/15", "bg-chart-1/30", "bg-chart-1/50", "bg-chart-1/70", "bg-chart-1/90"];

