/** Props for the legend of the stepped scale. */
export interface ScaleLegendProps {
  steps: ScaleStep[];
  formatValue: (value: number) => string;
  /** Writes a bare number with no unit, for the label under a step. */
  formatNumber: (value: number) => string;
  /** The step picked out on the map, or null. */
  pickedStep: number | null;
  onPickedStepChange: (step: number | null) => void;
}

/**
 * The five steps of the scale, lowest first, each labelled with the number it
 * starts at. Each step is a toggle: pressing it picks out the regions on that
 * step and fades the rest of the map back.
 */
export function ScaleLegend({ steps, formatValue, formatNumber, pickedStep, onPickedStepChange }: ScaleLegendProps) {
  return (
    <div role="group" aria-label="Scale. A stronger blue is higher. Press a step to pick out its regions." className="grid grid-cols-5 gap-1">
      {steps.map((step, index) => {
        const pressed = pickedStep === index;
        return (
          <Button
            key={index}
            variant="ghost"
            size="sm"
            aria-pressed={pressed}
            aria-label={`From ${formatValue(step.from)} to ${formatValue(step.to)}, ${step.count} ${step.count === 1 ? "region" : "regions"}`}
            onClick={() => onPickedStepChange(pressed ? null : index)}
            className="relative min-h-11 items-stretch"
          >
            {/* The pressed fill is a layer, so the button keeps its own variant. */}
            {pressed ? <span aria-hidden="true" className="absolute inset-0 rounded-lg bg-muted" /> : null}
            <span className="relative flex flex-1 flex-col justify-center gap-1 p-1 text-left">
              <span className={cn("h-2.5 w-full rounded-sm border border-border", STEP_SURFACE[index])} />
              <span className="text-xs font-normal text-muted-foreground tabular-nums">{formatNumber(step.from)}</span>
            </span>
          </Button>
        );
      })}
    </div>
  );
}

"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";

import { cn } from "@/lib/utils";

import { MAP_HEIGHT, MAP_WIDTH, type RankedRegion } from "../../lib/choropleth-regions";
import { STEP_FILL } from "./step-colours";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for the tile map. */
export interface TileMapProps {
  regions: RankedRegion[];
  /** Changes when the figure changes, so every tile fades to its new fill. */
  figureKey: string;
  /** Whether a change of figure sweeps across the map. Off for the first paint. */
  sweep: boolean;
  /** The region under the pointer or the list cursor, outlined and labelled. */
  activeId: string | null;
  /** The region whose detail is open. The map zooms to it. */
  selectedId: string | null;
  /** A step picked on the legend. Tiles on other steps fade back. */
  pickedStep: number | null;
  formatValue: (value: number) => string;
  onHover: (id: string | null) => void;
  onSelect: (id: string) => void;
}

// Critically damped: the camera arrives on the region and stops.
const CAMERA: Transition = { type: "spring", stiffness: 210, damping: 29, mass: 1 };
const INSTANT: Transition = { duration: 0 };
const ZOOM = 2.2;
// Where the three clinic dots sit around a tile's centre, in percent of the map.
const CLINIC_OFFSETS = [
  { left: -4, top: -5 },
  { left: 4.5, top: -1 },
  { left: -1.5, top: 6 },
];

/**
 * The invented territory as hexagon tiles filled by step. Hovering a tile
 * labels it with its value, and the open region is zoomed to on one spring.
 * The tiles are pointer targets only: the ranked list is the keyboard path.
 */
export function TileMap({ regions, figureKey, sweep, activeId, selectedId, pickedStep, formatValue, onHover, onSelect }: TileMapProps) {
  const reduceMotion = useReducedMotion();
  const selected = regions.find((item) => item.region.id === selectedId) ?? null;
  const labelled = regions.find((item) => item.region.id === activeId) ?? selected;
  const outlined = labelled?.region ?? null;
  const camera = selected
    ? { scale: ZOOM, x: `${(50 - selected.region.x) * ZOOM}%`, y: `${(50 - selected.region.y) * ZOOM}%` }
    : { scale: 1, x: "0%", y: "0%" };
  const labelAtTile = labelled !== null && selected === null;

  return (
    <div className="relative aspect-6/5 w-full overflow-hidden rounded-xl bg-muted/40">
      <motion.div initial={false} animate={camera} transition={reduceMotion ? INSTANT : CAMERA} className="absolute inset-3">
        <svg aria-hidden="true" viewBox={`0 0 ${MAP_WIDTH.toFixed(2)} ${MAP_HEIGHT}`} className="size-full overflow-visible">
          {regions.map(({ region, step }) => {
            const faded = (selectedId !== null && selectedId !== region.id) || (pickedStep !== null && pickedStep !== step);
            return (
              <g
                key={region.id}
                className={cn("cursor-pointer motion-safe:transition-opacity motion-safe:duration-200", faded ? "opacity-25" : undefined)}
                onPointerEnter={() => onHover(region.id)}
                onPointerLeave={() => onHover(null)}
                onClick={() => onSelect(region.id)}
              >
                <polygon points={region.outline} className="fill-muted" />
                <motion.polygon
                  key={`${figureKey}-${step}`}
                  points={region.outline}
                  initial={sweep && !reduceMotion ? { opacity: 0 } : false}
                  animate={{ opacity: 1 }}
                  // The delay grows from left to right, so the change crosses the map in well under a second.
                  transition={{ duration: 0.25, delay: (region.x / 100) * 0.4 }}
                  className={STEP_FILL[step]}
                />
              </g>
            );
          })}
          {outlined ? (
            <polygon
              points={outlined.outline}
              fill="none"
              strokeWidth="2"
              strokeLinejoin="round"
              vectorEffect="non-scaling-stroke"
              className="pointer-events-none stroke-foreground"
            />
          ) : null}
        </svg>
        {selected
          ? CLINIC_OFFSETS.map((offset, index) => (
              <span
                key={index}
                aria-hidden="true"
                className="left-(--x) top-(--y) pointer-events-none absolute size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full border border-card bg-foreground"
                style={
                  // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                  { "--x": `${selected.region.x + offset.left}%`, "--y": `${selected.region.y + offset.top}%` } as VarStyle
                }
              />
            ))
          : null}
      </motion.div>
      {labelled ? (
        <div
          aria-hidden="true"
          className={cn("pointer-events-none absolute inset-3", labelAtTile ? undefined : "flex items-start justify-center")}
        >
          <span
            className={cn(
              "flex flex-col items-center rounded-md border border-border bg-card px-2 py-1 text-center text-xs leading-4 shadow-sm",
              labelAtTile ? "absolute top-(--y) left-(--x) -translate-x-1/2 -translate-y-1/2" : undefined,
            )}
            style={
              // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
              { "--x": `${labelled.region.x}%`, "--y": `${labelled.region.y}%` } as VarStyle
            }
          >
            <span className="font-medium whitespace-nowrap">{labelled.region.name}</span>
            <span className="tabular-nums whitespace-nowrap text-muted-foreground">{formatValue(labelled.value)}</span>
          </span>
        </div>
      ) : null}
    </div>
  );
}
